INSERT INTO `pasos` (`id`, `id_etapa`, `paso`, `instruccion`, `code_producto`, `orden`) VALUES
(1, 1, 'MANGAS', 'Igualar mangas en pares y hacer piquetes a mitad. ', '1505003', 1),
(2, 1, 'CUERPO', 'Igualar mangas en pares y hacer piquetes a mitad. ', '1505003', 2),
(5, 4, 'PAQUETES', 'Armar paquetes por talla y cantidad.', '1505003', 1),
(8, 2, 'DELANTERO', 'Presenta un parche de color blanco en todos los colores.', '1505003', 1),
(9, 2, 'CUELLO', 'Acabado con ancho 1.5cm con refuerzo especial, parte espaldar.\n', '1505003', 1),
(10, 2, 'HOMBROS ', 'Unir con RM.3 ancho 0.4cm junto a su refuerzo.', '1505003', 3),
(11, 2, 'MANGAS', 'Pegado de mangas con RM.3 ancho de 0.4 cm, doblez de mangas a 2.2cm (ver tabla de medidas).', '1505003', 2),
(12, 2, 'SISA', 'RM.3 ancho 0.4cm.', '1505003', 4),
(13, 2, 'COSTADO', 'Cerrar con RM3 ancho de 0.4cm.\nCuidar los empalmes de recubre y sisas deberán coincidir. ', '1505003', 6),
(15, 2, 'FALDON', 'Acabado con RC2 DE 1/4 de separación y doblillado a 2.2cm y perfilar con vorde de 1mm.', '1505003', 7),
(16, 2, 'PEGADO/ASENTADO', 'Pegar cuello cuidando el compartido en el cabe de cuello, asentar con RC2 1/4 cuidando que no se presente caídos por ambos lados. ', '1505003', 8),
(17, 3, 'ESTAMPADO', 'Lleva 03 estampados en la parte delantera(letras) y espaldar(imagen) manga(letras). ', '1505003', 1),
(18, 2, 'ETIQUETA DE MARCA', 'Preparada con talla insertada a un costado de la etiqueta y pegados con atraques laterales en el centro de la espalda. ', '1505003', 9),
(19, 1, 'MANGAS', 'Doblar por la mitad de hacer una marca hacia el delantero de 0.6cm.\nIgualar cabes delantero, espalda en par antes de pegar cinta. ', '170510', 0),
(20, 1, 'CUERPO', 'Doblar por la mitad tomando como referencia el cuello y botar el revirado hacia abajo, la diferencia entre el delantero y la espalda mínimo debe ser de 5.5cm (cabe).Diferencia de sisa 2.5cm.  ', '170510', 0),
(21, 1, 'CABE DE CUELLO', 'Una vez que este armado la prenda (cuerpo y manga) procedemos a marcar y recortar cade de espalda y delantero, voltear prenda y dar medida de profundidad al cabe delantero. ', '170510', 0),
(27, 2, 'MANGAS', 'Pegado de tres cintas de buzo, 1ro ingresar por el puño y 2do ingresar por el cabe de cuello terminando por el puñ.\nRevisar los cables de manga que terminen iguales después de pegar las cintas. \nPegar mangas de RM3(ancho 0.5cm). Alto de puño ver tabla de medidas.\nTomar como referencia la sisa lo que sobra botar hacia el cuello.', '170510', 0),
(33, 3, 'BORDADO', 'El bordado de color negro es en la parte izquierda del polo prenda puesta. \nNOTA:El bordado se debe ver en prenda puesta. ', '170510', 0),
(34, 4, 'PAQUETES', 'Armar paquetes por talla.', '170510', 0),
(35, 1, 'MANGA', 'Igualar por pares.', '190516', 0),
(36, 1, 'CUERPO', 'Igualar delantero por la mitad. ', '190516', 1),
(37, 1, 'CABE DE CUELLO', 'Tener en cuenta mitad de la manga para abrir cabes por talla, debe tener manga unida al cuerpo y recubre de sisa antes de abrir cabe. ', '190516', 2),
(38, 2, 'PREPARADO DE CAPUCHA', 'Preparar capucha con forro unir en RM3, lleva recubre compartido de 1/4\".\nHacer ojalillos a medida.\nVoltear y pespuntar con CR1 a 2.5cm volteando. ', '190516', 0),
(49, 3, 'BORDADO', 'Lleva bordado MA en el lado izquierdo prenda puesta. \n', '190516', 0),
(50, 4, 'PAQUETES ', 'En paquetes por talla. ', '190516', 0),
(51, 1, 'CUERPO', 'Revisar que el porte quede igual por par. ', '190517', 0),
(53, 2, 'BOLSILLO', 'Marcar medida con molde desde filo de pretina delantero por cara.  Marcar abertura de bolsillo desde el filo 4 tapas por prenda, marcar por revés.\nPespunte de boca bolsillo a 1/4\". ', '190517', 0),
(54, 2, 'CINTA (3) BUSZO', 'Dar medida sin estirar cinta al porte de cuerpo espalda.\nParche cinta sobrecarga a espalda y delantero.\nPlanchar antes de ingresar a confección.  ', '190517', 0),
(55, 2, 'UNIR TIROS', 'Unir con remalle de 0.5 y pespuntar a 1/8\" con cadeneta de recubre 1 aguja. ', '190517', 0),
(56, 2, 'UNIR DELANTERO', 'Unir con remalle de 0.5 y pespuntar a 1/8\" con cadeneta de recubre 1 aguja. ', '190517', 0),
(57, 2, 'UNIR ESPALDA', 'Unir con remalle de 0.5 y pespuntar a 1/8\" con cadeneta de recubre 1 aguja. ', '190517', 0),
(58, 2, 'BOTAPIES', 'Dobles con recubre de 2 agujas con 1/4\" de separación. \nAlto de dobles(ver tabla de medidas).\n', '190517', 0),
(59, 2, 'PEGADO DE ELASTICO', 'Medida varia según calidad de elástico, referencia hoja de medidas.\nPreparar elástico con 1cm de cruce en (CR1) con 3 pasadas. ', '190517', 0),
(60, 2, 'RECUBRE DE ELÁSTICO', 'Primera pasada con recubre de 1/4 con empalme de 2 cm compartido.\nSegunda pasada con cadeneta de recubre a 1/4 de borde con empalme hacia la espalda de 2cm compartido. ', '190517', 0),
(61, 2, 'ETIQUETA DE MARCA', 'Costuras laterales con talla insertada, hilo al color de la prenda. ', '190517', 0),
(62, 4, 'PAQUETES', 'Armar  paquetes por talla. ', '190517', 0),
(63, 1, 'MANGAS', 'Igualar mangas en pares y hacer piquetes a mitad. ', '190518', 0),
(64, 1, 'CUERPO', 'Igualar delantero parte de la sisa con 0.6cm de diferencia con la espalda. ', '190518', 0),
(65, 1, 'CABE DE CUELLO', 'Diferencia entre espalda y delantero 3.2cm para dar cabe a delantero.\nEspalda cabe al ras.\nTerminada la prenda tiene una caída de 1.5cm. ', '190518', 0),
(66, 2, 'DELANTERO', 'Unir hombros RM3 con 0.6cm de ancho, con refuerzo de la misma tela. ', '190518', 0),
(67, 2, 'ESPALDA', 'Lleva estampado en la parte derecha de prenda puesta. ', '190518', 0),
(68, 2, 'MANGAS', 'Recubrir las mangas con RC2 de 1/8\" de separación y doblez(ver tabla de medidas). \nPegar mangas con RM3 con ancho de 6mm. Tiene caída de 1.5cm. \nCuidar que no quede el remalle al aire. ', '190518', 0),
(70, 2, 'SISA', 'Lleva recubre de una aguja cadeneta de ancho 0.4cm. ', '190518', 0),
(71, 2, 'COSTADO', 'Cerrar con RM3 con 0.5cm, cuidar los empalmes de sisas deberán coincidir.\nNo lleva etiqueta de contenido. ', '190518', 0),
(74, 2, 'FALDON', 'Acabado con RC2 de 1/( de separación y doblez(ver tabla de medidas).\nPerfilar con borde faldón a 1mm. \nEmpalme de costura hacia lado izquierdo prenda puesta 2cm. ', '190518', 0),
(75, 2, 'PUÑOS', 'Atraque de puños en CR1 con 1/8\" hacia la espalda. ', '190518', 0),
(76, 2, 'CUELLO', 'Cuello es de rib 1*1 color blanco. Empalme de cuello a 3cm de unión de hombro a espalda prenda puesta lado izquierdo. ', '190518', 0),
(77, 2, 'PEGAR CINTA DE CUELLO', 'Refuerzo de cuello hombro a hombro encintado especial 12 PPP.\nLleva recubre cadeneta de una aguja con un ancho de 1/8\" 12 PPP.\nEncintado especial. ', '190518', 0),
(79, 2, 'ASENTADO DE CUELLO', 'Asentar a 1/16\" cuidando que no presente caídos por ambos lados. La puntada debe ser igual al encintado y debe coincidir con la aguja del recubre.', '190518', 0),
(80, 2, 'ETIQUETA DE MARCA', 'Preparada con talla, Pegado  con atraques laterales sobre la costura del asentado. Pegar con hilo al color del cuerpo. ', '190518', 0),
(81, 3, 'ESTAMPADO', 'Lleva estampado lado derecho prenda puesta. ', '190518', 0),
(82, 4, 'PAQUETES', 'Armar paquetes por talla y cantidad. ', '190518', 0),
(83, 1, 'MANGAS', 'Se marca la manga con una linea de tiza para guía de pagado a 1cm del medio (manga doblada) hacia el delantero. ', '190519', 0),
(84, 1, 'CUERPO', 'Igualar y marcar delanteros para ubicación del bolsillo. ', '190519', 0),
(86, 1, 'CABE DE CUELLO', 'Marcar y recortar cabes después de recubre de mangas.', '190519', 0),
(87, 2, 'CUELLO', 'Cerrar cuello en CR1 a 1/4\". Luego debe voltear y realizar un pespunte 1/4\" en el contorno del cuello. ', '190519', 0),
(89, 1, 'CORTE', 'Revisar piezas que estén completas.\nRevisar el sentido del tejido.', '200901', 0),
(90, 1, 'MARCAR PIEZAS', 'Marcar piezas de acuerdo al molde y talla. ', '200901', 0),
(91, 1, 'PELAR PIEZAS', 'Pelar de acuerdo a la hoja de instrucción(1.7 cm). ', '200901', 0),
(92, 1, 'PEGAR CINTA MULTIFUSION ', 'Recortar cinta de acuerdo al tamaño de la pieza y graduar la temperatura de la plancha a 3°.', '200901', 0),
(93, 2, 'DELANTERO-COSTADILLO', 'Prepara tapeta(ancho=25 cm largo=15 cm).\nRemallar forro,fijar a tapeta preparado.\nMacar costadillo para el bolsillo y abrir. \nFijar tapeta/preparado) al borde del bolsillo(superior).\nFijar funda a borde bolsillo(inferior).\nEmbolsar funda,voltear y hacer pespunte 1/4.\nAtracar borde tapeta.', '200901', 0),
(94, 2, 'COSTADO DELANTERO/DELANTERO', 'Unir a 1.3 cm, costura francesa recortar parte interna y pespunte a 1/4\". ', '200901', 0),
(96, 2, 'ESPALDA', 'Unir centro de espalda a 1.3,costura francesa,recortar parte interna y pespuntar a 1/4\".\nUnir costadillos a espalda a 1.3 cm, costura francesa, recortar parte interna y pespuntar a 1/4\". ', '200901', 0),
(97, 2, 'MANGA-AMBAS UNIONES', 'Unir a 1.3 cm costura francesa,recortar parte interna,manga mayor sobrecarga a manga menor y pespunte a 1/4\".\nPelar la manga menor y mayor.', '200901', 0),
(98, 2, 'HOMBROS', 'Unir a 1.3 cm espalda sobre carga a delantero costura francesa,recortar y pespuntar a 1/4.', '200901', 0),
