(789, 2, 'BORDADO', 'EN ESPALDA, LADO IZQUIERDO PRENDA PUESTA A 3/4\" DE COSTURAS (VER FIGURA)', 'C-A18796-20', 3),
(790, 2, 'CAPUCHA', 'DOS PIEZAS UNIDAS EN EL CENTRO CON OVER Y LLEVA TAPETA PARA TAPAR EL OVER, (VER FIGURA). EN EL EXTERIOR SOLO SE VE UN PEEPUNTE Y EN EL INTERIOR DOS PESPUNTES.<br />\nLLEVA OJALES HORIZONTALES PARA QUE PASE EL REGULADOR DE CAPUCHA. (VER IMAGEN) <br />\nCAPUCHA CON VUELTA INTERIOR CON PESPUNTE DE QUIEBRE AL INTERIOR A 1/16\" DEL BORDE Y CR EN ASENTADO DE VUELTA, EL COLOR DEBE COINCIDIR CON EL COLOR DE INTERIOR DE CAPUCHA (VER MEDIDA DE CRUCE Y POSICION DE OJAL EN FIGURA)', 'C-A18796-20', 4),
(791, 2, 'COSTADO', 'APLICACIÓN DE LA MISMA TELA CENTRADA ENTRE ESPALDA Y DELANTERO, REVISAR FIGURA PORQUE EN LA SISA TERMINA EN ANGULO.<br />\nEL COSTADO Y COSTURA MANGA TERMINA CON OVER.', 'C-A18796-20', 5),
(792, 2, 'ESCOTE CUELLO', 'LLEVA REFUERZO DE CUELLO EN ESPALDA, DOBLE PESPUNTE AL INTERIOR Y 1 PESFUNTE CON CADENETA A 1/4\" QUE ES EL ASENTADO EN EL EXTERIOR<br />\nLLEVA ATRACADO LOS EXTREMOS DEL REGULADOR DE CAPUCHA. (VER FIGURA)<br />\nAPLICAR OVER EN HOMBROS', 'C-A18796-20', 6),
(793, 2, 'PRETINA CUERPO', 'DOBLADO APLICADO CON OVER Y CADENETA A 1/4\", QUEDA EMBOL SADO CON LATERALES DEL BOLSILI O.', 'C-A18796-20', 7),
(794, 2, 'PRETINA PUÑO', 'DOBLADO, LLEVA AGUJERO EMBOLSADO PARA DEDITO Y QUEDA GRADO A 1 1/4\" DE LA COSTURA DE CERRADO DE MANGA HACIA ADELANTE. (VER DETALLE EN IGURA) Y LLEVA BARTRACK EN EXTIEMOS DE ESTA ABERTURA (VER FIGURA) Y CR 3/16\" IN CONTORNO.<br />\nSE APLICAN CON OVER Y CADENETA A 1/4\" VER MEDIDAS DE UBICACIÓN EN FIGURA, MANGA SOBRECARGA A PUÑO.', 'C-A18796-20', 8),
