INSERT INTO `perfil_puesto` (`id`, `id_puesto`, `reporta_a`, `supervisa_a`, `interactua_con`, `reemplazado_por`, `objetivo`, `funciones`, `responsabilidades`, `equipo_utilizado`, `lugar_trabajo`, `requerimientos_fisicos`, `formacion_basica`, `formacion_basica_optima`, `conocimientos_especificos`, `experiencia_requerida`, `experiencia_requerida_optima`, `idioma`, `competencia_especifica`, `elaborado_por`, `aprobado_por`, `fecha_aprobacion`, `competencia_cardinal`) VALUES
(1, 1, 'Jefe Confecciones', '<ul>\n	<li>Supervisor de Ensamble</li>\n	<li>Inspector de Calidad de Confecciones</li>\n	<li>Operador de Ensamble</li>\n	<li>Manual de Ensamble</li>\n	<li>Operador de Corte</li>\n	<li>Manual de Corte</li>\n	<li>Manual de Acabados&nbsp;</li>\n</ul>\n', '<ul>\n	<li>Gerente General</li>\n	<li>Supervisor de Ensamble</li>\n	<li>&nbsp;</li>\n</ul>\n', 'Gerente General', 'Mejorar la productividad de los procesos de confecciones', '<ul>\n	<li>Elaborar planes, objetivos y metas de Ingenier&iacute;a Confecciones.</li>\n	<li>Informar a Gerente General de&nbsp;los avances,&nbsp;planes, objetivos y metas de Ingenier&iacute;a Confecciones.</li>\n	<li>Coordinar con &aacute;reas afines para el cumplimiento de planes, objetivos y metas de ingenier&iacute;a de confecci&oacute;n.</li>\n	<li>Elaborar analisis de capacidad mensual de corte, habilitado, emsamble, control de calidad y acabados.</li>\n	<li>Realizar coordinaciones para el plan y ejecuci&oacute;n de capacitaciones.</li>\n	<li>Supervisar las actividades de Ingenieria de confecciones.</li>\n	<li>Capacitar al personal de su &aacute;rea en temas de Seguridad y Sistemas de Gesti&oacute;n.</li>\n	<li>Coordinar con Supervisor de Ensamble la aplicacion de tiempo de prendas y/o m&eacute;todos de trabajo.</li>\n	<li>Manejar&nbsp;y proporcinar&nbsp;recursos al&nbsp;personal que esta a su cargo.</li>\n	<li>&nbsp; Participar del C&oacute;mite de calidad.</li>\n	<li>Evaluar el desempe&ntilde;o del las personas que estan a su cargo.</li>\n</ul>\n', '<ul>\n	<li>Responsable del logro de los objetivos definidos del &aacute;rea</li>\n	<li>Responsable de las actividades del &aacute;rea</li>\n	<li>Responsable de los bienes y recursos asignados.</li>\n	<li>Cumplir con el Reglamento de Seguridad y Salud en el Trabajo.</li>\n</ul>\n', '<ul>\n	<li>Computadora</li>\n	<li>Impresora</li>\n	<li>Cron&oacute;metros</li>\n	<li>Centimetro</li>\n	<li>Celular</li>\n</ul>\n', 'Área de confecciones', 'Ben estado de Salud.', 'Estudios superiores en Ingeniería Industrial', NULL, '<ul>\n	<li>Procesos de confecciones,</li>\n	<li>Conocimiento de Maquinas de coser</li>\n	<li>Ingenier&iacute;a de M&eacute;todos</li>\n	<li>Manejo de Personal</li>\n	<li>Costos</li>\n</ul>\n', '2 años de experiencia en procesos de confección.', NULL, 'Inglés Nivel Básico', '<ul>\n	<li>Lider</li>\n	<li>Integro</li>\n	<li>Comunicador</li>\n	<li>Tolerancia a la presi&oacute;n</li>\n	<li>Creativo</li>\n	<li>Innovador</li>\n	<li>Capacidad de Planificar, Hacer, Verificar y a Mejorar.</li>\n	<li>&nbsp;</li>\n</ul>\n', 'Gerente General', 'Gerente General', '2020-06-02', NULL),
(2, 2, 'Supervisor de ensamble', '', '', '', 'Ensamblar prendas cumpliendo las especificaciones indicadas en la ficha técnica y los estandares de calidad de la empresa.', '<ul>\n	<li>Realizar las operaciones de costura que sean necesarias para la confeccion de la prenda.</li>\n	<li>Realizar operaciones de remalle.</li>\n	<li>Realizar operaciones de recubre.</li>\n	<li>Realizar operaciones de ojal y bot&oacute;n seg&uacute;n el estilo y especificaciones a realizar.</li>\n	<li>Coordinar con la supervisora y los integrantes de l&iacute;nea de costura, las actividades a realizar.</li>\n	<li>Coordinar con otra areas afines.</li>\n</ul>\n', '<ul>\n	<li>Cumplir con las tareas asignadas por la supervisora.</li>\n	<li>Cumplir con las especificaciones y manual de operaciones.</li>\n	<li>Cumplir con el reglamento interno de seguridad y salud en el trabajo.</li>\n	<li>Responsable de los bienes y recursos asignados.</li>\n</ul>\n', '<ul>\n	<li>Centimetro</li>\n	<li>Tijeras</li>\n	<li>Plantillas para marcado</li>\n	<li>Especificaciones</li>\n	<li>Maquina de costura</li>\n	<li>Accesorios, topes, bobinas,carretes, tijeras, etc.</li>\n</ul>\n', 'Area de confecciones', 'Buen estado de salud y habilidades para realizar las operaciones.', 'Estudios tecnicos en confecciones ', NULL, '<p>Operatividad de maquinas de costura.</p>\n', '6 meses.', NULL, '', '<ul>\n	<li>Comunicacion</li>\n	<li>Tolerancia a la presion</li>\n	<li>Adaptacion al cambio</li>\n	<li>Iniciativa</li>\n	<li>Solucion de Problemas&nbsp;</li>\n	<li>Crativo y dinamico</li>\n</ul>\n', 'Jefe de Confecciones', 'Gerente General', '0000-00-00', NULL),
(3, 3, 'Supervisor de Ensamble', '', '<ul>\n	<li>Operario de Ensamble.</li>\n	<li>Supervisor de Ensamble.</li>\n</ul>\n', 'Manual de Ensamble', 'Habilitar de manera correcta las prendas durante el proceso de Ensamble.', '<ul>\n	<li>Repartir la costura seg&uacute;n las operaciones a realizar.</li>\n	<li>Marcar complementos (cuellos, back yoke, etiquetas, etc)</li>\n	<li>&nbsp;Igualar Mangas.</li>\n	<li>Recortar bastas de faldon y mangas.</li>\n	<li>Verificar mangas y cuerpos.</li>\n	<li>Abastecer de hilos al personal.</li>\n	<li>Recortar bastas de back yoke y bolsillos.</li>\n	<li>Realizar el vaporizado y planchado de prendas.</li>\n</ul>\n', '<ul>\n	<li>Realizar el trabajo seg&uacute;n las especificaciones del cliente e indicaciones de la supervisora.</li>\n	<li>Cumplir con reglamento interno de trabajo.&nbsp;</li>\n</ul>\n', '<ul>\n	<li>Tijeras</li>\n	<li>Centimetro</li>\n	<li>Piquetero</li>\n	<li>TIizas</li>\n	<li>Auja de mostacilla</li>\n	<li>Vaporizador</li>\n	<li>Plancha</li>\n</ul>\n', 'Área de confecciones', 'Buen estado de salud', 'Secundaria completa, estudios tecnicos en confecciones.', NULL, '', '1 mes de entrenamiento en el puesto.', NULL, '', '<ul>\n	<li>Comunnicador</li>\n	<li>Tolerancia ala presi&oacute;n</li>\n	<li>Adaptaci&oacute;n al cambio</li>\n	<li>Activo</li>\n	<li>Innovador</li>\n</ul>\n', 'Jefe de Ingenería de Confecciones', 'Gerente General', '0000-00-00', NULL),
(4, 8, 'Jefe Ingeniería de confecciones', '<p>---</p>', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Operario de ensamble</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Jefe de ingenieria de confecciones</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Analista de Diseño y atronaje</li></ol>', '-', 'Asegurar el correcto corte de la tela a trabajar ', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Realizar el tendido de la tela</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Realizar el corte de la tela en óptima calidad</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Revisar proporciones de trazos a trabajar</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Informar las cantidades despúes del corte al Manual de corte</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Cortar en forma proporcional a las cantidades del cliente</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Llenar correctamente los datos en la orden de corte</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Cuadrar la orden de corte</li></ol>', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Responsablede los bienes y recursos asignados</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Cumplir con el reglamento interno de \"Trabajo,seguridad y salud\" en&nbsp;el trabajo</li></ol>', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Máscara protectora</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Guante de malla metálica</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Lentes de seguridad</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Tapones auditivos</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Máquina tendedora</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Mesa de tendido</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Máquina de corte(manual)</li></ol>', 'Área de corte', 'Buen estado de salud y agudeza visual', 'Secundaria Trunca', 'Secundaria Completa', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>&nbsp;Manejo de máquinas de corte</li></ol>', '1 mes de entrenamiento ', '1 año manejando la máquina de corte vertical', 'Español', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>CREDIBILIDAD TÉCNICA</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>TEMPLE</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>COLABORACIÓN</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>PRODUCTIVIDAD</li></ol>', 'Jefe Ingeniería de confecciones ', 'Gerente General', '2023-07-27', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>FLEXIBILIDAD Y ADAPTACIÓN</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>INTEGRIDAD</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>INICIATIVA</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>COMPROMISO CON LA CALIDAD DE TRABAJO</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>RESPONSABILIDAD PERSONAL</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>TRABAJO EN EQUIPO</li></ol>'),
(5, 17, 'Jefe Ingeniería de confecciones', '<p>---</p>\n', '<ul>\n	<li>Jefe Ingenier&iacute;a de confecciones&nbsp;</li>\n	<li>Inspector de control,calidad y confeccion&nbsp;</li>\n</ul>\n', 'Operario de distribución fisica', 'Recibir y verificar las prendas entregadas por control de calidad, embalarlas y despachar según los requerimientos del cliente', '<ul>\n	<li>Verificar los lotes de prendas entregados por control</li>\n	<li>Embalar el producto final&nbsp;</li>\n	<li>Efectuar la distribuci&oacute;n</li>\n	<li>Recepcionar,verificar y almacenar los materiales e insumos para despachos</li>\n	<li>Almacenar adecuadamente el producto terminado</li>\n</ul>\n', '<ul>\n	<li>Solicitar a confecci&oacute;n la entrega de pedidos completos.</li>\n	<li>Del almacen de producto terminado,custodia e inventario</li>\n	<li>Cumplir el reglamento interno de &quot;Trabajo,seguridad y salud&quot; en el trabajo.</li>\n</ul>\n', '<ul>\n	<li>Computadora&nbsp;</li>\n	<li>Telef&oacute;no</li>\n	<li>Impresora</li>\n</ul>\n', 'Área de distribución ', 'Buen estado de salud ', 'Secundaria completa', NULL, '<ul>\n	<li>Manejo de almacenes&nbsp;</li>\n</ul>\n', '6 meses de entrenamiento ', NULL, 'Ingles básico ', '<ul>\n	<li>Comunicaci&oacute;n</li>\n	<li>Tolerancia a la presi&oacute;n</li>\n	<li>Adaptaci&oacute;n al cambio</li>\n	<li>Soluci&oacute;n de problemas</li>\n	<li>Iniciativa</li>\n	<li>Dinamismo - Energ&iacute;a</li>\n</ul>\n', 'Jefe Ingeniería de confecciones', 'Gerente General', '2020-01-01', NULL),
(6, 16, 'Accionistas de la empresa', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Jefe&nbsp;Ingenieria de confecciones</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Contador</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Operarios</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Analista de patronaje y desarrollo</li></ol>', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Todo el personal de la compañia</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Clientes</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Proveedores</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Accionistas</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Instituciónes gubernamentales</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Instituciones privadas</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Agentes financieros&nbsp;</li></ol>', 'Gerente General', 'Es el órgano directivo de mayor jerarquía,establece las políticas generales de la institución y ejerce la función normativa y reguladora en el marco establecido en las disposiciones legales', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Aprueba las políticas de la empresa</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Aprueba la memoria anual y el presupuesto</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Otorga los poderes que considere necesarios</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Ejerce la representación legal, administrativa y judicial ante instituciones y organismos nacionales o extranjeros, públicas y privadas</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Propone al directorio las políticas y estrategias de desarrollo de la empresa y controla su implementación</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Revisa el \"Plan estratégico\" asi como de los \"Planes operativos\" de la institución&nbsp;</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Revisa los estados financieros</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Mantiene actualizado los documentos normativos de gestión</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Dirige y coordina las acciones de las diferentes áreas a fin de cumplir con los fines y objetivos de la institución</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Controla y evalúa la ejecución presupuestal&nbsp;</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Realiza las relaciones públicas y atención a clientes del exterior y nacionales</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Revisa y prueba las políticas del&nbsp;sistema integrado&nbsp;de gestión ISO:9001 /&nbsp;ISO:45001</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Proporciona los recursos para el mantenimiento de los sistemas de gestión certificados&nbsp;</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Mantiene los requisitos de los sistemas de gestión correspondientes</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Velar por el bienestar y respeto de los colaboradores, manteniendo un ambiente laboral óptimo.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Motivar a los colaboradores a realizar las tareas asignadas con compromiso, responsabilidad y trabajo en equipo.</li></ol>', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Lidera la dirección de la empresa</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Lidera el sistema de gestión de calidad y seguridad y salud en el trabajo</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Responsable de las gestiones financieras de la empresa</li></ol>', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Computador</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Celular</li></ol>', 'Área administrativa', 'Buen estado de salud', 'Técnico en administración, gestion empresarial (culminado) o Ingeniero Indutria, administrador (egresado)', 'Administración, Ingenieria industrial (Titulado) ', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Sistema de gestión ISO 9001 / ISO 45001</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Admisnistración financiera&nbsp;</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Marketing</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Ventas</li></ol>', '1 año en cargos similares', '2 años en cargos similares', 'ingles bàsico', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Liderazgo para el cambío&nbsp;</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Pensamiento estratégico&nbsp;</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Manejo de personal</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Tolerancía a la presión</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Capacidad de planificar,hacer,verificar y mejorar continuamente</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Enfoque al cliente&nbsp;</li></ol>', 'Jefe de Gestión de Talento Humano', 'Gerente General', '2024-11-06', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>FLEXIBILIDAD Y ADAPTACIÓN</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>INTEGRIDAD</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>INICIATIVA</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>COMPROMISO CON LA CALIDAD DE TRABAJO</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>RESPONSABILIDAD PERSONAL</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>DINAMISMO - ENERGÍA</li></ol>'),
(7, 10, 'Jefe Ingeniería de confecciones ', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Operador de ensamble</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Manual de ensamble</li></ol>', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Jefe Ingeniría de confecciones</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Analista de protronaje y desarrollo</li></ol>', 'Jefe Ingeniería de confección ', 'Cumplir eficientemente con los programas de producción, funciones y responsabilidades ', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Ingresar prendas a las lineas de costura de acuerdo al programa</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Elaborar contra muestra con la muestra fisica antes de realizar la confección de un nuevo pedido</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Asignar y supervisar el trabajo de los operarios de línea a su cargo</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Coordinar con el Jefe Ingería de confección los pedidos a trabajar, asi como los avances</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Controlar los registros de costura asignada a la linea&nbsp;y el control diario de producción</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Coordinar con operarios los detalles de ejecución de costura</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Supervisar el cumplimiento de los estándares de costura, especificaciones, secuencias de operaciones y balance de linea</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Coordinar con el Jefe Ingeniería de confección modificaciones a la secuencia de operaciones&nbsp;&nbsp;</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Velar por el bienestar y respeto de los colaboradores, manteniendo un ambiente laboral óptimo.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Motivar a los colaboradores a realizar las tareas asignadas con compromiso, responsabilidad y trabajo en equipo.</li></ol>', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Responsable de los bienes y recursos asignados</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Evaluar el desempeño del personal a su cargo</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Conocer y aplicar los procedimientos de la linea de costura</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Cumplir con la cuota asignada a la linea</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Subir el porcentaje de eficiencia de la linea</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Controlar la asistencia del personal de linea</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Cumplir con el reglamento interno de \"Trabajo, seguridad y salud\" en el trabajo&nbsp;</li></ol>', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Centímetro</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Tijera</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Piquetera</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Calculadora</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Manual de operaciones&nbsp;</li></ol>', 'Área de confecciones ', 'Buen estado de salud', 'Secundaria Completa', 'Técnico en  confección textil, trunco o egresado', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Conocimiento en fichas tecnicas&nbsp;de costura</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Conocimiento de metodos de costura</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Conocimiento de procesos de confecciones&nbsp;</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Manejo de personal</li></ol>', '1 año de experiencia como supervisor en el área de confección y acabado', '2 años de experiencia como supervisor en el área de confección y acabado', 'ESPAÑOL', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Capacidad de planificación y organización</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>TOMA DE DECISIONES</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>ORIENTACIÓN AL CLIENTE INTERNO&nbsp;</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>LIDERAZGO</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Comunicación eficaz&nbsp;</li></ol>', 'Jefe Ingeniería de confecciones ', 'Gerente General', '2024-11-06', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>FLEXIBILIDAD Y ADAPTACIÓN</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>INTEGRIDAD</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>INICIATIVA</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>COMPROMISO CON LA CALIDAD DE TRABAJO</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>RESPONSABILIDAD PERSONAL</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>DINAMISMO - ENERGÍA</li></ol>'),
(8, 14, 'Jefe Ingería de confecciones ', '<p>---</p>\n', '<ul>\n	<li>Supervisor de confeccion y acabado</li>\n	<li>Jefe&nbsp;Ingenieria de confecciones&nbsp;</li>\n	<li>Operarios</li>\n</ul>\n', 'Inspector de control de calidad y confección', 'Controlar y garantizar que las prendas confeccionadas cumplan con las especificaciones del cliente', '<ul>\n	<li>Verificar los paquetes de prendas</li>\n	<li>Completar los paquetes de proceso&nbsp;</li>\n	<li>Inspeccionar paquetes de prendas completos&nbsp;</li>\n	<li>Separar prendas con defectos por confecci&oacute;n,manchas,etc (para su respectivo reproceso)</li>\n	<li>Registrar los defectos encontrados en los lotes de prendas&nbsp;</li>\n	<li>Armar paquetes completos de prendas inspeccionadas&nbsp;</li>\n</ul>\n', '<ul>\n	<li>Verificar la calidad de las prendas que pasan a despacho de costura&nbsp;</li>\n	<li>Responsable de los bienes y recursos asignados&nbsp;</li>\n	<li>Cumplir con el reglamento interno de &quot;Trabajo,seguridad y salud&quot; en el trabajo</li>\n</ul>\n\n<p>&nbsp;</p>\n', '<ul>\n	<li>Piqueteras</li>\n	<li>Cinta adhesiva</li>\n	<li>Cinta masking tape</li>\n	<li>Cartilla de tolerancias</li>\n	<li>&Uacute;tiles de escritorio&nbsp;</li>\n</ul>\n', 'Sector de control de calidad', 'Buen estado de salud, agudeza visual y visión cromática ', 'Secundaria Completa', 'Tecnico en confección textil, trunco o culminado', '<ul>\n	<li>M&eacute;todos de inspecci&oacute;n</li>\n	<li>Conocimiento de est&aacute;ndares de calidad</li>\n</ul>\n', '1 año en puestos similares en confección textil', '2 años en puestos similares en confección textil', 'Español', '<ul>\n	<li>CALIDAD Y MEJORA CONTINUA</li>\n	<li>Pensamiento anal&iacute;tico&nbsp;</li>\n	<li>Gesti&oacute;n y logro de objetivos</li>\n	<li>Conciencia organizacional&nbsp;</li>\n</ul>\n', 'Jefe Ingeniería de confecciones ', 'Gerente General', '2023-07-27', '<ul>\n	<li>FLEXIBILIDAD Y ADAPTACI&Oacute;N</li>\n	<li>INTEGRIDAD</li>\n	<li>INICIATIVA</li>\n	<li>COMPROMISO CON LA CALIDAD DE TRABAJO</li>\n	<li>RESPONSABILIDAD PERSONAL</li>\n	<li>DINAMISMO - ENERG&Iacute;A</li>\n</ul>\n'),
(9, 11, 'Gerente General', '<ul>\n	<li>Supervisor de confecciones y acabado&nbsp;</li>\n	<li>Operador de corte</li>\n	<li>Manual de corte</li>\n	<li>Operario de distribuci&oacute;n fisica</li>\n</ul>\n', '<ul>\n	<li>Gerente General</li>\n	<li>Supervisor de confecciones y acabado&nbsp;</li>\n	<li>Analista de patronaje y desarrollo</li>\n	<li>Manual de corte</li>\n	<li>Operario de distribuci&oacute;n fisica</li>\n</ul>\n', 'Gerente General', '', '', '', '<ul>\n	<li>&nbsp;</li>\n</ul>\n', 'Área de confecciones', 'Buen estado de salud', '', NULL, '<ul>\n	<li>Ingenier&iacute;a de Plantas&nbsp;</li>\n</ul>\n', '3 años de experiencia en procesos de confección ', NULL, 'Ingles nivel básico ', '', 'Gerente General', 'Gerente General', '2020-01-01', NULL),
(10, 15, 'Supervisor de confección y Acabado', '<p>---</p>\n', '<ul>\n	<li>Supervisor de confecci&oacute;n y Acabado</li>\n	<li>Jefe de Ingenier&iacute;a&nbsp;de confecciones</li>\n</ul>\n', 'Manual de acabado', 'Entregar paquetes de prendas dobladas y embolsadas conforme a las especificaciones y estándares de calidad.', '<ul>\n	<li>Verificar la cantidad de lotes de preendas con las tarjetas de producci&oacute;n</li>\n	<li>Vaporizar las prendas manualmente</li>\n	<li>Colocar los Hantg Tag a las prendas seg&uacute;n las especificaciones del pedido</li>\n	<li>Doblar y embolsar las prendas segun las especificaciones</li>\n</ul>\n', '<ul>\n	<li>Responsablede los bienes y recursos asignados</li>\n	<li>Cumplir con el reglamento interno de &quot;Trabajo,seguridad y salud&quot; en&nbsp;el trabajo</li>\n</ul>\n', '<ul>\n	<li>Dispensador de cinta adhesiva&nbsp;</li>\n	<li>Vaporizador manual</li>\n	<li>Cinta m&eacute;trica</li>\n	<li>Pistola Hanteadora</li>\n</ul>\n', 'Área de confección y acabado ', 'Buen estado de salud', '--', NULL, '<p>---</p>\n', '1 mes de entrenamiento en el puesto', NULL, '---', '<ul>\n	<li>CREDIBILIDAD T&Eacute;CNICA&nbsp;</li>\n	<li>TEMPLE&nbsp;</li>\n	<li>COLABORACI&Oacute;N&nbsp;</li>\n	<li>PRODUCTIVIDAD&nbsp;</li>\n</ul>\n', 'Jefe Ingeniería de confecciones ', 'Gerente General', '2023-01-03', '<ul>\n	<li>FLEXIBILIDAD Y ADAPTACI&Oacute;N</li>\n	<li>INTEGRIDAD</li>\n	<li>INICIATIVA</li>\n	<li>COMPROMISO CON LA CALIDAD DE TRABAJO</li>\n	<li>RESPONSABILIDAD PERSONAL</li>\n	<li>DINAMISMO - ENERG&Iacute;A</li>\n</ul>\n'),
(11, 21, 'Supervisor de confección y acabado ', '<p>--</p>\n', '<ul>\n	<li>Supervisor de confecci&oacute;n y acabado&nbsp;</li>\n	<li>Jefe Ingenieria de confecciones&nbsp;</li>\n	<li>Operador de corte&nbsp;</li>\n</ul>\n', 'Manual de corte', 'Habilitar de manera correcta las prendas durante el proceso de corte', '<ul>\n	<li>Dar el cabe a las mangas</li>\n	<li>Revisar el corte de las prendas</li>\n	<li>Hacer los tickets de identificacion de los paquetes</li>\n	<li>Bloquear los cuerpos y las mangas</li>\n	<li>Igualar bastas y sisas(listado)</li>\n	<li>Dar cabe a delanteros(listado)</li>\n	<li>Contar prenda por prenda(listado)</li>\n	<li>Enumerar pecheras</li>\n	<li>Cuadrar las ordenes de corte</li>\n	<li>Inspeccionar la calidad complementos rectilineos (tono,maching,medidas)</li>\n	<li>Armar y habilitar cuellos rectilineos</li>\n	<li>Informar las cantidades habilitadas(primeras y segundas)</li>\n</ul>\n', '<ul>\n	<li>Responsablede los bienes y recursos asignados</li>\n	<li>Cumplir con el reglamento interno de &quot;Trabajo,seguridad y salud&quot; en&nbsp;el trabajo</li>\n</ul>\n', '<ul>\n	<li>M&aacute;scara protectora</li>\n	<li>Lentes de seguridad</li>\n	<li>Tapones auditivos</li>\n	<li>Tijeras</li>\n	<li>Tiza</li>\n	<li>Regla met&aacute;lica</li>\n	<li>Cinta m&eacute;trica</li>\n</ul>\n', 'Área de corte', 'Buen estado de salud', '---', NULL, '<p>---</p>\n', '1 mes de entrenamiento en el puesto', NULL, '---', '<ul>\n	<li>CREDIBILIDAD T&Eacute;CNICA&nbsp;</li>\n	<li>TEMPLE&nbsp;</li>\n	<li>COLABORACI&Oacute;N&nbsp;</li>\n	<li>PRODUCTIVIDAD&nbsp;</li>\n</ul>\n\n<p>&nbsp;</p>\n', 'Jefe Ingeniería de confección ', 'Gerente General', '2020-01-01', '<ul>\n	<li>FLEXIBILIDAD Y ADAPTACI&Oacute;N</li>\n	<li>INTEGRIDAD</li>\n	<li>INICIATIVA</li>\n	<li>COMPROMISO CON LA CALIDAD DE TRABAJO</li>\n	<li>RESPONSABILIDAD PERSONAL</li>\n	<li>DINAMISMO - ENERG&Iacute;A</li>\n</ul>\n'),
(12, 12, 'Supervisor de confecciones y acabado', '<p>---</p>\n', '<ul>\n	<li>Supervisor de confecciones y acabado</li>\n	<li>Operador&nbsp;de ensamble</li>\n</ul>\n', 'Manual de ensamble', 'Habilitar de manera correcta las prendas durante el proceso de ensamble', '<ul>\n	<li>Repartir la costura seg&uacute;n las operaciones a realizar</li>\n	<li>Marcar complementos(cuellos)</li>\n	<li>Igualar mangas</li>\n	<li>Cortar bastas de fald&oacute;n y mangas</li>\n	<li>Verificar mangas y cuerpos&nbsp;</li>\n	<li>Abastecer de hilos al personal de costura</li>\n	<li>Recortar bastas de back joke y bolsillos</li>\n	<li>Realizar algunos procesos de las prendas,los que incluyan vaporizado y planchado&nbsp;</li>\n	<li>Verificar la cantidad de lotes de preendas con las tarjetas de producci&oacute;n</li>\n	<li>Vaporizar las prendas manualmente</li>\n	<li>Colocar los Hantg Tag a las prendas seg&uacute;n las especificaciones del pedido</li>\n	<li>Doblar y embolsar las prendas segun las especificaciones</li>\n</ul>\n', '<ul>\n	<li>Realizar el trabajo seg&uacute;n las especificaciones del cliente e indicaciones de la supervisora</li>\n	<li>Cumplir con el reglamento interno de&quot;Tranajo,seguridad y salud&quot; en el trabajo</li>\n</ul>\n', '<ul>\n	<li>Tijeras</li>\n	<li>Centimetro</li>\n	<li>Piquetera</li>\n	<li>Tizas</li>\n	<li>Aguja mostacilla</li>\n	<li>Vaporizador</li>\n	<li>Plancha</li>\n</ul>\n', 'Área de confección y acabado ', 'Buena salud y habilidades manuales', 'Secundaria Trunca', 'Secundaria completa', '<p>---</p>\n', '1 mes de entrenamiento ', '1 año en puestos manuales dentro del sector textil', 'Español', '<ul>\n	<li>CREDIBILIDAD T&Eacute;CNICA&nbsp;</li>\n	<li>TEMPLE&nbsp;</li>\n	<li>COLABORACI&Oacute;N&nbsp;</li>\n	<li>PRODUCTIVIDAD&nbsp;</li>\n</ul>\n', 'Jefe Ingeniería de confecciones ', 'Gerente General', '2023-07-27', '<ul>\n	<li>FLEXIBILIDAD Y ADAPTACI&Oacute;N</li>\n	<li>INTEGRIDAD</li>\n	<li>INICIATIVA</li>\n	<li>COMPROMISO CON LA CALIDAD DE TRABAJO</li>\n	<li>RESPONSABILIDAD PERSONAL</li>\n	<li>DINAMISMO - ENERG&Iacute;A</li>\n</ul>\n'),
(13, 13, 'Supervisor de confecciones y acabados', '<p>---</p>\n', '<ul>\n	<li>Supervisor de confecciones y acabados</li>\n	<li>Manual de ensamble</li>\n</ul>\n', 'Operador de ensamble', 'Ensamblar prendas cumpliendo las especificaciones y los estándares de calidad de la empresa', '<ul>\n	<li>Realizar las operaciones de costura recta, remalle, recubre que sean necesarias para la confecci&oacute;n de la prenda.</li>\n	<li>Realizar operaci&oacute;nes&nbsp;seg&uacute;n el estilo y especificaciones en ficha tecnica a trabajar.</li>\n	<li>Coordinar con la supervisora y los integrantes de la linea de costura,las actividades a realizar.</li>\n</ul>\n', '<ul>\n	<li>Cumplir con las tareas asignadas por la supervisora</li>\n	<li>Responsable de los bienes y recursos asignados</li>\n	<li>Cumplir con el reglamento interno de&quot;Trabajo,seguridad y salud&quot; en el trabajo</li>\n</ul>\n', '<ul>\n	<li>Centimetro</li>\n	<li>Tijeras</li>\n	<li>Plantillas para marcado</li>\n	<li>Especificaciones</li>\n	<li>M&aacute;quina de costura</li>\n	<li>Accesorios de m&aacute;quina de costura</li>\n</ul>\n', 'Área de confección ', 'Buen estado de salud y habilidades manuales ', 'Secundaria Trunca', 'Secundaria Completa', '<ul>\n	<li>Conocimiento en manejo de m&aacute;quinas de costura</li>\n</ul>\n', '1 mes de entrenamiento ', '1 año operando máquinas de costura', 'Español', '<ul>\n	<li>CREDIBILIDAD T&Eacute;CNICA&nbsp;</li>\n	<li>TEMPLE&nbsp;</li>\n	<li>COLABORACI&Oacute;N&nbsp;</li>\n	<li>PRODUCTIVIDAD&nbsp;</li>\n</ul>\n\n<p>&nbsp;</p>\n', 'Jefe Ingeniería de confecciones', 'Gerente General', '2023-07-27', '<ul>\n	<li>FLEXIBILIDAD Y ADAPTACI&Oacute;N</li>\n	<li>INTEGRIDAD</li>\n	<li>INICIATIVA</li>\n	<li>COMPROMISO CON LA CALIDAD DE TRABAJO</li>\n	<li>RESPONSABILIDAD PERSONAL</li>\n	<li>DINAMISMO - ENERG&Iacute;A</li>\n</ul>\n'),
(14, 22, 'Gerente General', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Supervisor de confecciones y acabado&nbsp;</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Enacargado de corte</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Operarios</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Supervisor de Mantenimiento</li></ol>', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Gerente General</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Supervisor de confecciones y acabado&nbsp;</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Analista de patronaje y desarrollo</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Manual de corte</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Operarios</li></ol>', 'Jefe Ingeniería de confecciones', 'Mejorar la productividad de los procesos de confecciones', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Elaborar planes, objetivos y metas de Ingeniería de confecciones</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Informar al Gerente General los avances de los planes, objetivos y metas&nbsp;de Ingeniería de confecciones</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Coordinar con Áreas afines para el cumplimiento de planes, objetivos y metas de Ingeniería de confecciones</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Elaborar análisis de capacidad mensual corte, habilitado, ensamble, control de calidad y acabados</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Proponer y dirigir proyectos de mejora de corte, habilitado, ensamble, control de calidad y acabados</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Realizar coordinaciones para la preparación de ejecución de capacitaciones</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Supervisar las actividades de integrantes</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Capacitar al personal de su área en diferentes temas de los sistemas de gestión</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Coordinar con Gerente General los cambios de estilo y&nbsp;balance de línea</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Participar en reuniones de \"Apertura de ordenes\"</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Coordinar con Gerente General a verificación de tiempo y/o métodos de trabajo</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Manejo del personal y evaluar el desempeño del personal a cargo</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Participar en el comité de confecciones.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Velar por el bienestar y respeto de los colaboradores, manteniendo un ambiente laboral óptimo.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Motivar a los colaboradores a realizar las tareas asignadas con compromiso, responsabilidad y trabajo en equipo.</li></ol>', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Responsable del logro de los objetivos del área</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Responsable de las actividades del área</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Responsables de los bienes y recursos asignados</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Cumplir con el reglamento interno de \"Trabajo,seguridad y salud\" en&nbsp;el trabajo</li></ol>', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Computador</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Impresora</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Cronómetro</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Calculadora</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Celular</li></ol>', 'Área de confección y acabado ', 'Buen estado de salud', 'Técnico en administración, gestion empresarial (culminado) o Ingeniero Indutrial, administrador (egresado)', 'Administración, Ingenieria industrial (Titulado) ', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Procesos de confecciones</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Conocimiento de maquinas de coser</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Ingenieria de Métodos</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Ingeniería de Plantas</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Administracion de personal</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Costos&nbsp;</li></ol>', '1 Mes de  entrenamieno', '1 año en cargos similares', 'Español', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>INFLUENCIA Y NEGOCIACIÓN&nbsp;</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Capacidad de planificar y organizar</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Credibilidad técnica</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Pensamiento conceptual&nbsp;</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Pensamiento analítico&nbsp;</li></ol>', 'Jefe de Gestion de Talento Humano', 'Gerente General', '2024-11-06', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>FLEXIBILIDAD Y ADAPTACIÓN</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>INTEGRIDAD</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>INICIATIVA</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>COMPROMISO CON LA CALIDAD DE TRABAJO</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>RESPONSABILIDAD PERSONAL</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>DINAMISMO - ENERGÍA</li></ol>'),
(15, 20, 'Gerente General', '<p>---</p>\n', '<ul>\n	<li>Jefe Ingenier&iacute;a de confeccion&nbsp;</li>\n	<li>Supervisor de confecciones y acabado</li>\n	<li>Encargado de corte</li>\n	<li>Gerente General</li>\n</ul>\n', 'Analista de patronaje y diseño', 'Generación de moldes,simulaciones y consumos ', '<ul>\n	<li>Creaci&oacute;n e innovaci&oacute;n de modelos</li>\n	<li>Generar moldes para cada desarrollo de prenda</li>\n	<li>Generar simulacioes para cada desarrollo de prenda</li>\n	<li>Completar/generar tablas de medidas en el &quot;Sistema Integral&quot;</li>\n	<li>Calcular el consumo para muestras y ordenes de producci&oacute;n&nbsp;</li>\n	<li>Brindar el soporte t&eacute;cnico a los dem&aacute;s procesos productivos&nbsp;</li>\n	<li>Cumplir con los procedimientos del &quot;Sistema de gesti&oacute;n de la calidad de la compa&ntilde;ia&quot;</li>\n</ul>\n', '<ul>\n	<li>Asegurar la correcta generaci&oacute;n de moldes,simulaciones y el c&aacute;lculo de consumos</li>\n	<li>Cumplir con el reglamento interno de &quot;Trabajo,seguridad y salud&quot;en el trabajo.</li>\n</ul>\n', '<ul>\n	<li>Computador</li>\n	<li>Celular</li>\n</ul>\n', 'Área de diseño y desarrollo', 'Buen estado de salud,agudeza visual y visión cromática ', 'Secundaria Completa', 'Técnico en confección textil', '<ul>\n	<li>Conocimiento en procesos textiles y confecciones&nbsp;</li>\n	<li>Manejo de software de patronaje (Gerber Tecnologi)&nbsp;</li>\n	<li>Manejo de programas basicos de escritorio&nbsp;</li>\n</ul>\n', '1 mes de entrenamiento', '1 año en cargos similares', 'Español', '<ul>\n	<li>CALIDAD Y MEJORA CONTINUA&nbsp;</li>\n	<li>Credibilidad t&eacute;cnica</li>\n	<li>INNOVACI&Oacute;N Y CREATIVIDAD&nbsp;</li>\n	<li>TOMA DE DECISIONES&nbsp;</li>\n</ul>\n', 'Jefe de Gestión de Talento Humano', 'Gerente General', '2020-07-27', '<ul>\n	<li>FLEXIBILIDAD Y ADAPTACI&Oacute;N</li>\n	<li>INTEGRIDAD</li>\n	<li>INICIATIVA</li>\n	<li>COMPROMISO CON LA CALIDAD DE TRABAJO</li>\n	<li>RESPONSABILIDAD PERSONAL</li>\n	<li>DINAMISMO - ENERG&Iacute;A</li>\n</ul>\n'),
(16, 26, 'Gerente General', '<p>Todos los trabajdores:</p>\n\n<ul>\n	<li>Administrativos</li>\n	<li>Operativos</li>\n	<li>Visitantes</li>\n	<li>Clientes</li>\n	<li>Proveedores</li>\n	<li>Contratistas</li>\n</ul>\n', '<ul>\n	<li>Gerente General</li>\n	<li>Jefes de &aacute;reas</li>\n	<li>Todos los trabajadores</li>\n</ul>\n', 'Gerente General o Coordinador Sistemas Integrados de Gestión', 'Administrar y mantener los Sistemas Integrados de Gestión de Peruvian Dress SAC, incluye las actividades de planificar, hacer, verificar y mejorar  los procesos, realizar auditorias internas y coordinar las auditorias de certificación.', '<ul>\n	<li>Administrar el sistema de gesti&oacute;n integrado.</li>\n	<li>Participara en el proceso de planeamiento estrat&eacute;gico.</li>\n	<li>Desarrollar, proponer y coordinar con Gerencia las pol&iacute;ticas, objetivos y planes de acci&oacute;n.</li>\n	<li>verificar que el &aacute;rea cuente con los recursos necesarios.</li>\n	<li>Liderar las auditorias internas de los sistemas integrados de gesti&oacute;n.</li>\n	<li>Controlar el cumplimiento de compromisos de la pol&iacute;tica de calidad.</li>\n	<li>Promover la mejora continua de los procesos.</li>\n	<li>Controlar el funcionamiento de los sistemas integrados de gesti&oacute;n.</li>\n	<li>Coordinar la auditorias externas de los sistemas integrados de gesti&oacute;n.</li>\n	<li>Administrar las funciones operativas del &aacute;rea de seguridad.</li>\n</ul>\n', '<ul>\n	<li>Ser coordinador de los sistemas integrados de gesti&oacute;n.</li>\n	<li>De la organizacion y administraci&oacute;n de los sistemas integrados de gestion haciendolos compatibles con los objetivos de la organizaci&oacute;n.</li>\n	<li>Del la toma de conciencia de los colaboradores de Peruvian Dress SAC</li>\n	<li>Del cumplimiento de los compromisos de implementacion de los sistemas integrados de gesti&oacute;n.</li>\n	<li>De los recursos necesarios para los sistemas integrados&nbsp;de gestion.</li>\n	<li>De la aplicaci&oacute;n de los procedimientos de los sistemas integrados de gesti&oacute;n.</li>\n</ul>\n', '<ul>\n	<li>PC, celular</li>\n</ul>\n', 'Toda la organización', 'Buen estado físico', 'Capacitado en Auditorias Internas enfocado en ISO 9001 o 45001', 'Certificado como Auditor Interno en ISOS 9001 o 45001', '<ul>\n	<li>Sistemas de gesti&oacute;n.</li>\n	<li>Interpretaci&oacute;n de la norma ISO:9001 e ISO:45001</li>\n	<li>Auditorias internas.</li>\n	<li>Gesti&oacute;n de procesos.</li>\n</ul>\n', 'Contar con certificado como Auditor Interno en ISO:45001', '1 año en cargos similares', 'Español', '<ul>\n	<li>Liderazgo</li>\n	<li>Capacidad de planificar y organizar&nbsp;</li>\n	<li>Orientaci&oacute;n hacia el cliente interno y externo&nbsp;</li>\n	<li>PROFUNDIDAD EN EL CONOCIMIENTO DE LOS PRODUCTOS&nbsp;</li>\n	<li>Pensamiento anal&iacute;tico&nbsp;</li>\n</ul>\n', 'Jefe de Gestion de Talento Humano', 'Gerente General', '2023-07-27', '<ul>\n	<li>FLEXIBILIDAD Y ADAPTACI&Oacute;N</li>\n	<li>INTEGRIDAD</li>\n	<li>INICIATIVA</li>\n	<li>COMPROMISO CON LA CALIDAD DE TRABAJO</li>\n	<li>RESPONSABILIDAD PERSONAL</li>\n	<li>DINAMISMO - ENERG&Iacute;A</li>\n</ul>\n');
INSERT INTO `perfil_puesto` (`id`, `id_puesto`, `reporta_a`, `supervisa_a`, `interactua_con`, `reemplazado_por`, `objetivo`, `funciones`, `responsabilidades`, `equipo_utilizado`, `lugar_trabajo`, `requerimientos_fisicos`, `formacion_basica`, `formacion_basica_optima`, `conocimientos_especificos`, `experiencia_requerida`, `experiencia_requerida_optima`, `idioma`, `competencia_especifica`, `elaborado_por`, `aprobado_por`, `fecha_aprobacion`, `competencia_cardinal`) VALUES
(17, 31, 'GERENTE GENERAL', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Gerente General</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Jefes</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Coordinadores</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Supervisores</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Encargados</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Operadores</li></ol>', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Gerente General</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Jefes</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Coordinadores</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Supervisores</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Encargados</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Operadores</li></ol>', 'Gerente General', 'Cumplir con los objetivos estratégicos de la organización en el desarrollo  de la Gestion del talento humano.', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Definir estrategias para&nbsp;atraer y retener colaboradores.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Definir las politicas concernientes a la organizacion, seleccion, contratacion, capacitacion y desarrollo.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Definir estrategias para el desarrollo del los colaboradorres y mejora para el desempeño en el puesto.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Brindar asesoria y facilitar el cumplimiento de los objetivos organizacionales.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Hacer firmar y evaluar el cumplimiento de los contratos.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Participar&nbsp;y ejcutar los planes estrategicos de la organizacion.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Seguimiento de las acciones de mejora del clima organizacional.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Elaborar planilla de pagos.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Registrar y hacer firmar formatos de vacaciones.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Ingresar informacion a los relojes de marcaciones y datos ERP..</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Hacer firmar boletas depago y entrega a los colaboradores.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Planificar, organizar y ejecutar programas de salud.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Gestionar tramites en essalud.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Coordinar con el personal ingresante y/o por cesar examenes medicos ocupacionales.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>&nbsp;Velar por el bienestar y respeto de los colaboradores, manteniendo un ambiente laboral óptimo.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Motivar a los colaboradores a realizar las tareas asignadas con compromiso, responsabilidad y trabajo en equipo.</li></ol><p><br></p>', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Del apoyo, asesoria y desarrollo de los colaboradores.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Del bienestar de los trabajadores.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Del cumplimiento de los objetivos organizacionales.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Cumplir con el reglamenmto interno de trabajo.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Cumplir con el procedimiento e intrucciones del sistema integrado de gestion ISO:9001 e ISO:45001.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Del orden de la informacion y registros.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>De los murales y botiquines.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>De los documentos.</li></ol><p>&nbsp;</p>', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Laptop.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Archivadores</li></ol><p>&nbsp;</p>', 'Toda la organizacion', 'Buen estado de salud', 'Técnico en administración, gestion empresarial (culminado) o Ingeniero Indutrial, administrador (egresado)', 'Administración, Ingenieria industrial, Psicólogo (Titulado) ', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Gestion de personal.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Conocimiento de primeros auxilios.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Conocimiento en seguridad y salud en el trabajo.</li></ol><p>&nbsp;</p><p>&nbsp;</p>', '1 mes de entrenamiento', '1 año en puestos similares', 'Español', '<p>&nbsp;</p><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Liderazgo</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>INFLUENCIA Y NEGOCIACIÓN&nbsp;</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Capacidad de planificar y organizarA</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>(DIRECCIÓN DE EQUIPOS DE TRABAJO&nbsp;</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Orientación al cliente interno y externo&nbsp;</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Desarrollo y autodesarrollo del talento&nbsp;</li></ol><p>&nbsp;</p>', 'Jefe Gestion de Talento Humano', 'Gerente General', '2024-11-06', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>FLEXIBILIDAD Y ADAPTACIÓN</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>INTEGRIDAD</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>INICIATIVA</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>COMPROMISO CON LA CALIDAD DE TRABAJO</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>RESPONSABILIDAD PERSONAL</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>DINAMISMO - ENERGÍA</li></ol>'),
(18, 34, 'GERENTE GENERAL', '<p>Gerente general<br />\nCoordinadores<br />\nSupervisores<br />\nEncargados<br />\nProveedores</p>\n', '<ul>\n	<li>Gerente General</li>\n	<li>Coordinadores</li>\n	<li>Supervisores</li>\n	<li>Encargados</li>\n	<li>Proveedores</li>\n	<li>Clientes</li>\n</ul>\n', 'GERENTE GENERAL', 'Definir la estrategia comercial y contribuir al desarrollo de negocio a través del desarrollo de productos, innovación y marketing', '<ul>\n	<li>Definir y dirigir la estrategia comercial.</li>\n	<li>Analizar e investigar mercados, (en conjunto con operaciones).</li>\n	<li>B&uacute;squeda permanente de nuevas ideas.</li>\n	<li>Analizar y desarrollar productos y servicios.</li>\n</ul>\n', '<ul>\n	<li>Implementar estrategias de ventas, de organizar, dirigir, coordinar y controlar los esfuerzos de ventas de la empresa.</li>\n	<li>Estudiar y analizar el mercado, consultando diversas fuentes de informaci&oacute;n.</li>\n	<li>Coordinar las actividades de ventas con otras &aacute;reas de la empresa, log&iacute;stica, producci&oacute;n, etc.</li>\n	<li>Mantener contacto permanente con los clientes, proveedores, distribuidores para mantener informado de las novedades del producto y las promociones.</li>\n	<li>Planear las campa&ntilde;as promocionales, publicidad y toda idea que contribuya al incremento de ventas de la empresa.</li>\n	<li>Coordinar el desplazamiento de los vendedores, la distribuci&oacute;n del producto y material promocional en los puntos de venta.</li>\n	<li>Establecer sistemas de control de los objetivos y cuotas de mercado, ventas, distribuci&oacute;n y rentabilidad de los productos</li>\n</ul>\n', '<p>Laptop<br />\nArchivadores<br />\nCalculador</p>\n', 'Toda la Organización', 'Buen estado de salud', 'Técnico en administración, gestion empresarial (culminado), Comercial o Ingeniero Indutrial, administrador (egresado)', 'Administración, Ingenieria industrial, Comercial(Titulado)', '<ul>\n	<li>Gesti&oacute;n comercial</li>\n	<li>Conocimientos b&aacute;sicos de log&iacute;stica</li>\n	<li>Costos</li>\n	<li>Excel</li>\n</ul>\n', '1 mes de entrenamiento', '1 año en puestos similares', 'Español', '<ul>\n	<li>Liderazgo&nbsp;</li>\n	<li>Orientaci&oacute;n al cliente interno y externo&nbsp;</li>\n	<li>DIRECCI&Oacute;N DE EQUIPOS DE TRABAJO&nbsp;</li>\n	<li>INFLUENCIA Y NEGOCIACI&Oacute;N</li>\n	<li>Capacidad de planificar y organizar&nbsp;</li>\n</ul>\n\n<p>&nbsp;</p>\n', 'Jefe de Gestión de Talento Humano', 'GERENTE GENERAL', '2023-07-27', '<ul>\n	<li>FLEXIBILIDAD Y ADAPTACI&Oacute;N</li>\n	<li>INTEGRIDAD</li>\n	<li>INICIATIVA</li>\n	<li>COMPROMISO CON LA CALIDAD DE TRABAJO</li>\n	<li>RESPONSABILIDAD PERSONAL</li>\n	<li>DINAMISMO - ENERG&Iacute;A</li>\n</ul>\n'),
(19, 36, 'GERENTE GENERAL', '<p>SUPERVISOR DE CONFECCIONES, OPERARIOS DE ENSAMBLE, OPERARIO DE CORTE, MANUAL DE ENSAMBLE</p>', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>GERENTE GENRAL</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Jefe de Ingenieria de Confecciones</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Inspector de Calidad y Confección</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Supervisor de Confección y acabado</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Operador de Ensamble</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Encargado de Corte</li></ol>', 'Jefe de Ingenieria de Confecciones', 'Garantizar la operatividad eficiente y segura de los equipos e infraestructura de la organización mediante el mantenimiento preventivo, correctivo y la gestión efectiva de recursos, en línea con los principios del sistema integrado de gestión.', '<ol><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Planificar y coordinar el mantenimiento preventivo y correctivo de equipos e infraestructura.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Supervisar la instalación y buen funcionamiento de máquinas de confección, equipos tecnológicos y estructurales.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Verificar el cumplimiento de normativas de seguridad en instalaciones y sistemas eléctricos/mecánicos.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Coordinar con contratistas y proveedores para la ejecución de obras o mejoras de infraestructura.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Controlar inventario de equipos, herramientas e insumos de mantenimiento.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Implementar estrategias de mejora continua en el área de mantenimiento e infraestructura.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Inspeccionar periódicamente las instalaciones para detectar fallos o áreas de mejora.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Elaborar reportes para la dirección.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Asegurar el cumplimiento de los estándares del sistema integrado de gestión (calidad, seguridad).</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Gestionar presupuestos y requerimientos de compras del área.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Fomentar un ambiente de trabajo colaborativo, seguro y motivador.</li></ol>', '<ol><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Cumplir con las normas de seguridad y salud ocupacional.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Asegurar el correcto uso y conservación de los equipos asignados.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Controlar el inventario de equipos y herramientas asignados.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Gestionar proyectos de renovación o expansión de infraestructura.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Velar por la formación continua del personal técnico.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Garantizar la eficiencia energética y sostenibilidad de las instalaciones.</li></ol>', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Herramientas eléctricas y manuales</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Equipos de medición eléctrica y mecánica</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Software de gestión de mantenimiento (ERP)</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Equipos de protección personal (EPP)</li></ol>', 'Toda la empresa (interiores, exteriores y sistemas asociados)', 'Buen estado físico', 'Secundaria completa ', 'Técnico en mantenimiento de equipos trunco o culminado', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Solido conocimiento técnico en reparación de maquinas de coser</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Manejo de instrumentos y herramientas de confección</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Conocimientos sólidos en calibración de máquinas de coser</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Conocimientos en seguridad&nbsp;</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Conocimientos básicos en mecánica industrial</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Gestión de mantenimiento (preventivo y correctivo)</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Manejo de software de mantenimiento</li></ol>', '2 años en cargos similares', '3 años como supervisor de infraestructura o mantenimiento', 'Español', '<ol><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Liderazgo técnico</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Capacidad de organización y resolución de problemas</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Comunicación clara y asertiva</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Análisis crítico</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Orientación al cumplimiento de objetivos y estándares de calidad</li></ol>', 'JEFE DE GESTION DE TALENTO HUMANO', 'GERENTE GENERAL', '2024-05-23', '<ol><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Adaptabilidad al cambio</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Ética e integridad</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Proactividad</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Compromiso con la mejora continua</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Responsabilidad y autonomía</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Energía y dinamismo</li></ol>'),
(20, 37, 'GERENCIA', '<p>Todo el personal</p>', '<p>Todo el personal</p><p>&nbsp;</p>', 'Jefe de Gestion de Talento Humano', 'Reducir el indice de accidentabilidad y de incidentes', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Promover la salud y seguridad en el trabajo.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Asesorar y vigilar el cumplimiento de la normativa nacional.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Hacer recomendaciones apropiadas para el mejoramiento de las condiciones y el medio ambiente de trabajo,</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Velar porque se lleven a cabo las medidas adoptadas y examinar su eficiencia.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Velar por el bienestar y respeto de los colaboradores, manteniendo un ambiente laboral óptimo.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Motivar a los colaboradores a realizar las tareas asignadas con compromiso, responsabilidad y trabajo en equipo.</li></ol>', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Coordinar al cuerpo de vigilancia.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Dar seguimiento a las acciones de vigilancia.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Vincular al equipo de seguridad con la empresa.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Realizar acciones de prevención.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Capacitar al personal.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Diseñar planes de emergencia.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Tomar medidas correctivas en caso de incumplimiento.</li></ol><p>&nbsp;</p>', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Botiquin</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Formatos de seguridad</li></ol>', 'Toda la empresa', 'Buena Salud', 'Capacitacion certificada en Seguridad y salud en el trabajo', 'Diplomado en Seguridad y salud en el rabajo', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Resoluciones Ministeriales</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Elaboracion de planes de contingencia</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Elaboracion de plan de vigilancia</li></ol>', '1 mes de entrenamiento', '1 año como supervisor en SST', 'Español', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>MANEJO DE CRISIS</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>GESTION Y LOGRO DE OBJETIVOS</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>COLABORACION</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>TOLERANCIA ALA PRESION DE TRABAJO</li></ol>', 'JEFE DE GESTION DE TALENTO HUMANO', 'GERENTE GENERAL', '2024-11-06', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>FLEXIBILIDAD Y ADAPTACIÓN</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>INTEGRIDAD</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>INICIATIVA</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>COMPROMISO CON LA CALIDAD DE TRABAJO</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>RESPONSABILIDAD PERSONAL</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>TRABAJO EN EQUIPO</li></ol>');
